"""CPUS-CHECK1 / MAIN 13:05 item 2: SHA-verified MOVE of superseded gate control dirs gate_coop2 and gate_coop5
from cpuQ to the cpuS archive. Copy (rsync -aH, home-relative) -> remote sha256 of every file -> fresh source
identity+sha re-check -> unlink source files only; empty dirs removed; a MOVED_TO_CPUS.json receipt stays in
each top dir. Symlinks and protected names are never moved. Any failure before unlink keeps everything."""
import hashlib, json, os, re, subprocess, sys, time
from pathlib import Path
HOME = Path('/home/ubuntu')
CTL = HOME/'coopmwm20261104_cpus_checking_q'/('move_'+time.strftime('%H%M'))
DEST_HOST = ['ssh', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=20', '-o', 'StrictHostKeyChecking=yes', '-o', 'UserKnownHostsFile=/home/ubuntu/coopmwm20261104_cpus_checking_q/known_hosts_cpus', '-o', 'IdentitiesOnly=yes', '-i', str(HOME/'.ssh/id_ed25519_boxsync'), 'ubuntu@172.17.16.6']
DEST = '/home/ubuntu/coopmwm20261104_cpus_checking/archive_cpuq'
BAD = re.compile(r'sealed|holdout|heldout|cal_split|chunk5|j4b|inc1|hetdata_truth', re.I)
DIRS = [a for a in sys.argv[1:] if not a.startswith('--')]
dry = '--dry-run' in sys.argv
assert all(re.fullmatch(r'(coopmwm2026110[0-9]_[A-Za-z0-9_]+(/[A-Za-z0-9_]+)?|entrant)', d) for d in DIRS) and DIRS, DIRS
NAME = {d: re.compile(re.escape(d)+r'(?![0-9A-Za-z_])') for d in DIRS}
PAT = {d: re.compile(re.escape('/home/ubuntu/'+d)+r'(?![0-9A-Za-z_])') for d in DIRS}
import glob as _g
LIVE_JSON = sorted(_g.glob('/home/ubuntu/coopmwm20261104_v2v_coop3/*.json')+_g.glob('/home/ubuntu/coopmwm20261102_warm1/*.json')+_g.glob('/home/ubuntu/coopmwm20261104_launch3_coop8/*.json'))


def references():
    """dir -> reasons it is referenced (live PID cwd/argv/environ/fd, symlink target, live binding JSON)."""
    refs = {d: [] for d in DIRS}
    me = os.getpid()
    for pd in Path('/proc').glob('[0-9]*'):
        if pd.name == str(me):
            continue
        try:
            items = [os.readlink(pd/'cwd')]
            items += (pd/'cmdline').read_bytes().decode('utf-8', 'replace').split('\0')
            items += (pd/'environ').read_bytes().decode('utf-8', 'replace').split('\0')
            try:
                items += [l.split()[-1] for l in (pd/'maps').read_text().splitlines() if len(l.split()) >= 6]
            except OSError:
                pass
            for fd in (pd/'fd').iterdir():
                try:
                    items.append(os.readlink(fd))
                except OSError:
                    pass
        except OSError:
            continue
        blob = '\n'.join(items)
        for d in DIRS:
            if PAT[d].search(blob):
                refs[d].append('pid '+pd.name)
    for top, dn, fn in os.walk('/home/ubuntu'):
        dn[:] = [x for x in dn if not BAD.search(x) and os.path.relpath(os.path.join(top, x), '/home/ubuntu') not in DIRS and x not in ('miniconda3', '.cache')]
        for n in dn+fn:
            p = os.path.join(top, n)
            if os.path.islink(p):
                t = os.readlink(p)
                for d in DIRS:
                    if NAME[d].search(t):
                        refs[d].append('symlink '+p)
    for j in LIVE_JSON:
        try:
            txt = open(j).read()
        except OSError:
            continue
        for d in DIRS:
            if NAME[d].search(txt):
                refs[d].append('binding '+j)
    return refs


REFS = references()
blocked = {d: r[:5] for d, r in REFS.items() if r}
DIRS = [d for d in DIRS if not REFS[d]]


def ident(p):
    st = p.stat(); h = hashlib.sha256()
    with p.open('rb') as f:
        for c in iter(lambda: f.read(1 << 20), b''): h.update(c)
    return dict(rel=str(p.relative_to(HOME)), bytes=st.st_size, inode=st.st_ino, nlink=st.st_nlink,
                mtime_ns=st.st_mtime_ns, sha256=h.hexdigest())


CTL.mkdir(parents=True, exist_ok=True)
files, skipped = [], []
for d in DIRS:
    for dp, dn, fn in os.walk(HOME/d):
        for f in fn:
            p = Path(dp)/f
            if p.is_symlink() or BAD.search(str(p.relative_to(HOME))) or not p.is_file():
                skipped.append(str(p)); continue
            files.append(ident(p))
st = os.statvfs('/home/ubuntu'); free0 = st.f_bavail*st.f_frsize
man = dict(unix=time.time(), dirs=DIRS, blocked=blocked, freeable_bytes=sum(f['bytes'] for f in files if f['nlink'] == 1), files=len(files), bytes=sum(f['bytes'] for f in files),
           multi_link=sum(f['nlink'] > 1 for f in files), skipped=skipped, cpuq_free_before=free0, dest=DEST, dry_run=dry)
(CTL/('DRY_MANIFEST.json' if dry else 'MANIFEST.json')).write_text(json.dumps(dict(man, entries=files)))
print(json.dumps(man))
if dry:
    sys.exit(0)
lst = CTL/'FILES.txt'; lst.write_text(''.join(f['rel']+'\n' for f in files))
subprocess.run(DEST_HOST+[f'mkdir -p {DEST}'], check=True, timeout=60)
p = subprocess.run(['rsync', '-aH', '--files-from', str(lst), '-e', ' '.join(DEST_HOST[:-1]), str(HOME)+'/',
                    DEST_HOST[-1]+':'+DEST+'/'], capture_output=True, text=True, timeout=3600)
if p.returncode:
    (CTL/'FAILED_TRANSFER.json').write_text(json.dumps(dict(rc=p.returncode, err=p.stderr[-2000:]))); sys.exit(2)
code = ('import hashlib,json,sys\nfrom pathlib import Path\nE=json.loads(sys.stdin.read());out={}\n'
        'for e in E:\n p=Path(%r)/e["rel"]\n out[e["rel"]]=hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else None\n'
        'print(json.dumps(out))\n' % DEST)
rp = subprocess.run(DEST_HOST+['cat > /tmp/gate_move_verify.py'], input=code, text=True, timeout=60, check=True)
v = subprocess.run(DEST_HOST+['python3 /tmp/gate_move_verify.py'], input=json.dumps([dict(rel=f['rel']) for f in files]),
                   capture_output=True, text=True, timeout=1800)
remote = json.loads(v.stdout)
bad = [f['rel'] for f in files if remote.get(f['rel']) != f['sha256']]
(CTL/'REMOTE_VERIFIED.json').write_text(json.dumps(dict(unix=time.time(), checked=len(remote), bad=bad, manifest_sha256=hashlib.sha256((CTL/'MANIFEST.json').read_bytes()).hexdigest())))
if bad:
    print('REMOTE MISMATCH', len(bad)); sys.exit(3)
removed = 0
for f in files:
    p = HOME/f['rel']; cur = ident(p)
    if {k: cur[k] for k in ('bytes', 'inode', 'mtime_ns', 'sha256')} != {k: f[k] for k in ('bytes', 'inode', 'mtime_ns', 'sha256')}:
        (CTL/'STOPPED_SOURCE_CHANGED.json').write_text(json.dumps(dict(rel=f['rel'], removed_so_far=removed))); sys.exit(4)
    p.unlink(); removed += 1
for d in DIRS:
    for dp, dn, fn in sorted(os.walk(HOME/d), key=lambda x: -len(x[0])):
        if Path(dp) != HOME/d and not os.listdir(dp):
            os.rmdir(dp)
    (HOME/d/'MOVED_TO_CPUS.json').write_text(json.dumps(dict(moved_to='cpuS:'+DEST+'/'+d, manifest=str(CTL/'MANIFEST.json'),
        authority='MAIN disk-urgent (CPUS-CHECK1)', unix=time.time())))
st = os.statvfs('/home/ubuntu'); free1 = st.f_bavail*st.f_frsize
(CTL/'COMPLETE.json').write_text(json.dumps(dict(unix=time.time(), removed=removed, cpuq_free_before=free0, cpuq_free_after=free1)))
subprocess.run(DEST_HOST+[f'cat > {DEST}/GATE_MOVE_1305_MANIFEST.json'], input=(CTL/'MANIFEST.json').read_text(), text=True, timeout=120)
with (HOME/'coopmwm20261104_cpus_checking_q'/'MOVES.jsonl').open('a') as f:
    f.write(json.dumps(dict(unix=time.time(), control=str(CTL), dirs=DIRS, blocked=blocked, files=len(files),
                            bytes=sum(x['bytes'] for x in files), removed=removed, free_before=free0, free_after=free1,
                            dest='cpuS:'+DEST, manifest_sha256=hashlib.sha256((CTL/'MANIFEST.json').read_bytes()).hexdigest()))+'\n')
print(json.dumps(dict(removed=removed, free_before=free0, free_after=free1, blocked=blocked)))
